def m(v):
    if v is None: return ""
    s=f"{abs(v):,.0f}"
    return f"(${s})" if v<0 else f"${s}"
def var(a,b):
    if a is None or b is None: return ("","")
    d=a-b; pct=(d/abs(b)*100) if b else 0
    return (f"(${abs(d):,.0f})" if d<0 else f"${d:,.0f}", f"{pct:.0f}%")
def row(label,a,b=None,p=None,bold=False):
    cls="b" if bold else ""
    bv=var(a,b) if b is not None else ("","")
    pv=var(a,p) if p is not None else ("","")
    return (f'<tr class="{cls}"><td class="lbl">{label}</td><td class="n">{m(a)}</td>'
            f'<td class="n">{m(b)}</td><td class="n v">{bv[0]}</td><td class="n v">{bv[1]}</td>'
            f'<td class="n">{m(p)}</td><td class="n v">{pv[0]}</td></tr>')
def bsrow(label,cur,prior=None,bold=False,sub=False):
    cls="b" if bold else ("sub" if sub else "")
    if prior is not None:
        d=cur-prior; ds=f"(${abs(d):,.0f})" if d<0 else f"${d:,.0f}"
        pct=f"{(d/abs(prior)*100):.0f}%" if prior else ""
    else: ds=""; pct=""
    return (f'<tr class="{cls}"><td class="lbl">{label}</td><td class="n">{m(cur)}</td>'
            f'<td class="n">{m(prior) if prior is not None else ""}</td>'
            f'<td class="n v">{ds}</td><td class="n v">{pct}</td></tr>')

